import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const i=JSON.parse(`{"title":"支持 export default 和默认导入的简易 ESM 加载器实现。","description":"很好！我们继续进入 第三章： 🧠 目标功能 在上章基础上，加入对 export default 和默认导入的支持： 示例代码要支持： // a.mjsexport const foo 'FOO';export default 'I am the default export'。","frontmatter":{"title":"支持 export default 和默认导入的简易 ESM 加载器实现。","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"很好！我们继续进入 第三章： 🧠 目标功能 在上章基础上，加入对 export default 和默认导入的支持： 示例代码要支持： // a.mjsexport const foo 'FOO';export default 'I am the default export'。","sidebarWeight":41,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/支持 export default 和默认导入的简易 ESM 加载器实现。.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/支持 export default 和默认导入的简易 ESM 加载器实现。.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/支持 export default 和默认导入的简易 ESM 加载器实现。.md"}`),s={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/支持 export default 和默认导入的简易 ESM 加载器实现。.md"};function n(p,e,l,d,m,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="支持-export-default-和默认导入的简易-esm-加载器实现。" tabindex="-1">支持 export default 和默认导入的简易 ESM 加载器实现。 <a class="header-anchor" href="#支持-export-default-和默认导入的简易-esm-加载器实现。" aria-label="Permalink to &quot;支持 export default 和默认导入的简易 ESM 加载器实现。&quot;">​</a></h1><blockquote><p>本节目标：理解“支持 export default 和默认导入的简易 ESM 加载器实现。”的核心思路，并能把它用于实际开发或面试表达。 很好！我们继续进入 <strong>第三章：</strong></p></blockquote><p><strong>🧠</strong> <strong>目标功能</strong> 在上章基础上，加入对 export default 和默认导入的支持： 示例代码要支持： // a.mjsexport const foo = &#39;FOO&#39;;export default &#39;I am the default export&#39;; // b.mjsimport def, { foo } from &#39;./a.mjs&#39;;console.log(&#39;默认导入：&#39;, def);console.log(&#39;具名导入：&#39;, foo);</p><p><strong>✅</strong> <strong>文件结构回顾</strong> esloader/├── main.js // 启动程序├── loader.js // 核心加载器├── a.mjs└── b.mjs</p><p><strong>✍️</strong> <strong>第一步：更新 a.mjs</strong> export const foo = &#39;FOO&#39;;export default &#39;I am the default export&#39;;</p><p><strong>✍️</strong> <strong>第二步：更新 b.mjs</strong> import def, { foo } from &#39;./a.mjs&#39;;console.log(&#39;默认导入：&#39;, def);console.log(&#39;具名导入：&#39;, foo);</p><p><strong>⚙️</strong> <strong>第三步：修改 loader.js 处理 default 导出</strong> const fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;); const moduleGraph = new Map(); async function loadModule(filePath) { const absPath = path.resolve(__dirname, filePath); if (moduleGraph.has(absPath)) { return moduleGraph.get(absPath).namespace; } const code = fs.readFileSync(absPath, &#39;utf-8&#39;); // 改进版：解析 import + default const importRegex = /import\\s+(?😦\\w+)\\s*,\\s*)?(?:{?([\\w\\s,]<em>)}?)?\\s+from\\s+<a href="./.+">&#39;&quot;</a>[&#39;&quot;]/g; const exportNamedRegex = /export\\s+(const|let|var|function)\\s+(\\w+)/g; const exportDefaultRegex = /export\\s+default\\s+(.</em>)/; const dependencies = []; let match; while ((match = importRegex.exec(code))) { const [, defaultImport, namedImports, depPath] = match; dependencies.push({ defaultImport, namedImports, depPath }); } const namespace = {}; moduleGraph.set(absPath, { namespace }); for (const dep of dependencies) { const depNamespace = await loadModule(dep.depPath); if (dep.defaultImport) { Object.defineProperty(namespace, dep.defaultImport, { enumerable: true, get: () =&gt; depNamespace.default }); } if (dep.namedImports) { const names = dep.namedImports.split(&#39;,&#39;).map(s =&gt; s.trim()); for (const name of names) { Object.defineProperty(namespace, name, { enumerable: true, get: () =&gt; depNamespace[name] }); } } } let transformedCode = code .replace(importRegex, &#39;&#39;) // 移除 import .replace(exportNamedRegex, &#39;namespace.$2 =&#39;) .replace(exportDefaultRegex, &#39;namespace.default = $1&#39;); const fn = new Function(&#39;namespace&#39;, &#39;exports&#39;, transformedCode); fn(namespace, namespace); return namespace;} module.exports = { loadModule };</p><p><strong>🚀</strong> <strong>第四步：运行 main.js</strong> const { loadModule } = require(&#39;./loader&#39;); (async () =&gt; { await loadModule(&#39;./b.mjs&#39;);})();</p><p><strong>✅</strong> <strong>输出结果</strong> 默认导入： I am the default export具名导入： FOO</p><p><strong>🔍</strong> <strong>小结</strong><strong>已支持：</strong></p><ul><li>export const ...</li><li>export default ...</li><li>import defaultExport, { named } from &#39;...&#39;</li></ul><p><strong>模拟特性：</strong></p><ul><li>模块缓存 ✔️</li><li>实时绑定（live binding）✔️</li><li>默认导出 ✔️</li><li>简易 import/export 静态解析 ✔️</li></ul><p><strong>🔮</strong> <strong>下一章建议（第四章）</strong> 如果你还想继续，可以进入：</p><ol><li><strong>使用 AST 工具 acorn 更精准地解析 import/export</strong></li><li><strong>模拟 top-level await 异步模块加载（如远程 fetch 模块）</strong></li><li><strong>将模块打包成一个文件：模拟 Rollup/Vite 的打包过程</strong></li><li><strong>模拟 Tree Shaking：只导入使用到的 export</strong></li></ol><p>你对哪部分更感兴趣？我们就按那条路线继续写教程 🔧 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const u=t(s,[["render",n]]);export{i as __pageData,u as default};
